  function nvPhoto(v){var ck=VENUE_PHOTO[nvSlug(v.venue||'')];if(ck&&NV_PHOTOS[ck])return '<img loading="lazy" src="'+NV_PHOTOS[ck]+'" alt="'+((v.venue||'')+', '+v.city)+'">';var mon=MONUMENTS[nvSlug(v.city)];if(mon)return '<div class="nv-mon"><svg viewBox="0 0 120 120" aria-hidden="true">'+mon+'</svg></div>';var lbl=v.venue?v.venue:'Lieu à venir';return '<div class="nv-ph"><span></span><b>'+lbl+'</b></div>';}
  function nvBadge(v){var s=nvStatut(v);if(s==='cloture')return '<span class="nv-hi closed">\u00c9v\u00e9nement cl\u00f4tur\u00e9</span>';if(s==='ouvert')return '<span class="nv-hi live">\u25CF Inscriptions ouvertes</span>';return '<span class="nv-hi soon">\u00c0 venir \u2728</span>';}
  function nvBtns(v){
    var st=nvStatut(v);
    var odoo=v.odoo||NV_ODOO_FALLBACK;
    var expo='<a class="nv-cta alt" style="background:#FCE3F0;color:#B4005F;border-color:var(--rose)" href="'+expoTarget(v)+'">Exposer / plus de détails</a>';
    if(v.tbd){return '<span class="nv-closed">Ville d\u00e9voil\u00e9e bient\u00f4t</span>'+expo;}
    var cand;
    if(st==='ouvert'){cand='<a class="nv-cta" style="background:var(--blue);border-color:var(--blue);color:#fff" href="'+(v.ms||'#')+'">Je m’inscris comme candidat</a>';}
    else if(st==='avenir'){cand=v.candList?('<a class="nv-cta" style="background:var(--blue);border-color:var(--blue);color:#fff" href="'+v.candList+'">\u00catre alert\u00e9\u00b7e</a>'):('<a class="nv-cta" style="background:var(--blue);border-color:var(--blue);color:#fff" href="#" onclick="openCandForm(\''+String(v.city).replace(/\'/g,"\\'")+'\');return false;">\u00catre alert\u00e9\u00b7e</a>');}
    else{cand='<span class="nv-closed">\u00c9v\u00e9nement cl\u00f4tur\u00e9</span>';}
    return cand+expo;
  }
  function nvMeta(v,up){if(up)return v.coprod?('\uD83E\uDD1D '+v.coprod):'Programmation en cours \u00b7 pr\u00e9-inscriptions';return v.count?('\uD83D\uDC65 '+v.count):'';}
  function nvCard(v){
    var up=nvStatut(v)==='avenir'; var venue=v.venue?v.venue:'Lieu \u00e0 venir';
    return '<article class="nv-card '+(nvStatut(v)==='cloture'?'past':'')+' '+(up?'soon':'')+'" data-city="'+nvSlug(v.city)+'" style="--ac:'+v.cA+';--ac-txt:'+ct(v.cA)+'">'
      +'<div class="nv-top">'+nvPhoto(v,up)+nvBadge(v)+'</div>'
      +'<div class="nv-b"><div class="nv-row"><h3><a href="'+urlVille(v.city)+'" title="Village des Recruteurs de '+v.city+', informations pratiques">'+v.city+'</a></h3><span class="nv-date">'+v.date+'</span></div>'
      +'<div class="nv-venue">\uD83D\uDCCD '+venue+(v.region?' \u00b7 '+v.region:'')+'</div>'
      +'<div class="nv-meta2">'+nvMeta(v,up)+'</div>'
      +'<div class="nv-ctas">'+nvBtns(v)+'</div></div></article>';
  }
  function nvPins(list){return list.map(function(v){var xy=NV_XY[v.city];if(!xy)return '';var cls=(function(s){return s==='cloture'?'past':(s==='ouvert'?'open':'soon');})(nvStatut(v));
    return '<g class="nv-pin '+cls+'" data-city="'+nvSlug(v.city)+'" tabindex="0" transform="translate('+xy[0]+','+xy[1]+')">'
      +'<circle class="nv-halo" r="14" style="fill:'+v.cA+'"></circle><circle class="nv-dot" r="7" style="fill:'+v.cA+'"></circle>'
      +'<g class="nv-lbl"><rect x="10" y="-11" rx="6" height="22" width="'+Math.max(52,v.city.length*8+16)+'" fill="#fff" stroke="var(--line)"></rect><text x="18" y="4">'+v.city+'</text></g></g>';}).join('');}
  function nvWire(){
    document.querySelectorAll('#page-evenements .nv-pin').forEach(function(p){var c=p.dataset.city;
      function card(){return document.querySelector('#nv-cards .nv-card[data-city="'+c+'"]');}
      p.addEventListener('mouseenter',function(){p.classList.add('active');var k=card();if(k)k.classList.add('active');});
      p.addEventListener('mouseleave',function(){p.classList.remove('active');var k=card();if(k)k.classList.remove('active');});
      function go(){var k=card();if(k){k.scrollIntoView({behavior:'smooth',block:'center'});k.classList.remove('pulse');void k.offsetWidth;k.classList.add('pulse');}}
      p.addEventListener('click',go);p.addEventListener('keydown',function(e){if(e.key==='Enter')go();});});
    document.querySelectorAll('#nv-cards .nv-card').forEach(function(k){var c=k.dataset.city;var pin=document.querySelector('#page-evenements .nv-pin[data-city="'+c+'"]');
      k.addEventListener('mouseenter',function(){if(pin)pin.classList.add('active');});
      k.addEventListener('mouseleave',function(){if(pin)pin.classList.remove('active');});});
  }
  function nvFrise(y){
    var host=document.getElementById('nv-ov');if(!host)return;
    var list=(y==='2027'?villages2027:villages2026);
    var n=list.length, lastPast=-1;
    list.forEach(function(e,i){if((e.state||'')==='past')lastPast=i;});
    var prog=lastPast>=0?((lastPast+0.5)/n*97):0;
    var stops=list.map(function(e){
      var st=e.tbd?'soon':((e.state==='past')?'past':(e.state==='open'?'open':'soon'));
      var sym=st==='past'?'✓':(st==='open'?'●':'○');
      var cnt=e.count?('<span class="nvf-cnt">'+String(e.count).replace(/\s*candidats?/i,'')+'</span>'):'';
      var dt=(e.date||'').replace(/\s*20\d\d/,'');
      return '<button class="nvf-stop '+st+(e.tbd?' tbd':'')+'" style="--ac:'+(e.cA||'#08324F')+';--ac-txt:'+ct(e.cA||'#08324F')+'" data-city="'+nvSlug(e.city)+'">'
        +'<span class="nvf-city">'+e.city+'</span>'
        +'<span class="nvf-node '+st+'">'+sym+'</span>'
        +'<span class="nvf-mois">'+(e.mois||'').toUpperCase()+'</span>'
        +cnt+'</button>';
    }).join('');
    var ynote=(y==='2027')?' · dates et lieux à confirmer fin septembre 2026':'';
    host.innerHTML='<div class="nvf-head"><div class="nvf-title">La tournée en un coup d’œil<small>'+n+' rendez-vous · Tournée '+y+ynote+'</small></div>'
      +'<div class="nvf-stats"><span><b>85+</b> éditions depuis 2015</span><span><b>150 000+</b> candidats accompagnés</span><span><b>400+</b> entreprises / an</span></div></div>'
      +'<div class="nvf-rail"><div class="nvf-prog" style="width:'+prog+'%"></div>'+stops+'</div>';
    host.querySelectorAll('.nvf-stop').forEach(function(b){b.addEventListener('click',function(){var c=document.querySelector('#nv-cards .nv-card[data-city="'+b.dataset.city+'"]');if(c){c.scrollIntoView({behavior:'smooth',block:'center'});c.classList.remove('pulse');void c.offsetWidth;c.classList.add('pulse');}});});
  }
  function renderNV(y){
    var list=y==='2027'?villages2027:villages2026;
    var cards=document.getElementById('nv-cards');if(cards)cards.innerHTML=list.map(nvCard).join('');nvFrise(y);
    var pins=document.getElementById('nv-pins');if(pins)pins.innerHTML=nvPins(list);
    var t=document.getElementById('nv-mtitle');if(t)t.textContent=(y==='2027'?'8 Villages \u00b7 Tourn\u00e9e 2027':'7 Villages \u00b7 Tourn\u00e9e 2026');
    var note=document.getElementById('nv-note');if(note)note.textContent=(y==='2027'?'Programmation pr\u00e9visionnelle 2027 \u2014 dates, lieux et co-productions confirm\u00e9s au fil de l’eau.':'Tourn\u00e9e 2026 \u2014 inscription candidats via Matching Square, d\u00e9tails exposant sur Odoo.');
    nvWire();
  }
  function setYear(y){document.querySelectorAll('.nv-yr').forEach(function(b){b.classList.toggle('on',b.dataset.year===y);});renderNV(y);}
  window.setYear=setYear;
  (function(){if(!document.getElementById('nv-cards'))return;renderNV('2026');if(EVT_LINKS_URL){fetch(EVT_LINKS_URL,{cache:'no-store'}).then(function(r){return r.json();}).then(function(cfg){applyLinks(cfg.links||cfg);var b=document.querySelector('.nv-yr.on');renderNV(b?b.dataset.year:'2026');}).catch(function(){});}})();

  /* VILLAGE DETAIL */
  function openVillage(i){
    var v=villages2026[i];if(!v)return;
    document.getElementById('vd-hero').innerHTML=
      '<div class="vd-hero" style="background:linear-gradient(135deg,'+v.cA+','+v.cB+')">'
      +'<span class="eyebrow" style="background:rgba(255,255,255,.2);color:#fff">'+v.region+'</span>'
      +'<h1 style="color:#fff;margin:.6rem 0 .2rem">Village des Recruteurs · '+v.city+'</h1>'
      +'<div class="vd-meta"><div class="m"><b>'+v.date+'</b><span>Date de l’édition</span></div>'
      +'<div class="m"><b>'+v.venue+'</b><span>Lieu</span></div>'
      +'<div class="m"><b>'+v.count+'</b><span>Affluence attendue</span></div></div></div>';
    document.getElementById('vd-body').innerHTML=
      '<h2 style="font-size:1.5rem;margin-bottom:.4rem">Pourquoi exposer à '+v.city+'</h2>'
      +'<p class="lead" style="margin-bottom:1rem">Une journée pour rencontrer des candidats motivés et pré-qualifiés de toute la région '+v.region+'. Stand privatif, affluence garantie et mise en relation ciblée orchestrée par Job Events.</p>'
      +'<div class="feature"><div><b>Candidats pré-qualifiés</b><p>Matching Square oriente vers vous les profils qui correspondent à vos offres.</p></div></div>'
      +'<div class="feature"><div><b>15 à 40 candidats qualifiés</b><p>En moyenne, par exposant et par édition.</p></div></div>'
      +'<div class="feature"><div><b>Bilan chiffré</b><p>Suivi en temps réel et rapport d’impact après l’événement.</p></div></div>'
      +'<h3 style="font-size:1.15rem;margin:1.6rem 0 .2rem">Secteurs qui recrutent sur cette édition</h3>'
      +'<div class="sector-tags">'+v.sectors.map(function(s){return '<span class="t">'+s+'</span>';}).join('')+'</div>';
    document.getElementById('vd-aside').innerHTML=
      '<span class="eyebrow blue">Village de '+v.city+'</span>'
      +'<h3 style="margin-top:.5rem">Exposer sur ce Village</h3>'
      +'<p>Réservez votre stand et recevez le dossier complet (formats, tarifs, plan de salle).</p>'
      +'<a class="btn btn-blue" style="width:100%;justify-content:center;margin-bottom:.55rem" href="'+expoTarget(v)+'">'+(v.odoo?'Réserver un stand · voir l’événement':'Réserver un stand')+'</a>'
      +(v.state==='past'
        ? '<div class="btn btn-off" style="width:100%;justify-content:center;margin-bottom:.55rem">Édition terminée</div>'
        : (v.ms
          ? '<a class="btn btn-ghost" style="width:100%;justify-content:center;margin-bottom:.55rem" href="'+v.ms+'">S’inscrire comme candidat</a>'
          : '<a class="btn btn-ghost" style="width:100%;justify-content:center;margin-bottom:.55rem" href="#" onclick="openCandForm(\''+v.city+'\');return false;">S’inscrire comme candidat</a>'))
      +'<div class="price-tag">Stand privatif dès 990 € HT · CVthèque incluse</div>';
    go('village-detail');
  }

