  function coter(img){
    if(img.hasAttribute("width")||img.hasAttribute("height"))return;
    var s=img.getAttribute("src")||"";
    var i=s.lastIndexOf("/img/");if(i<0)return;
    var d=DIM[s.slice(i+4)];if(!d)return;
    img.setAttribute("width",d[0]);img.setAttribute("height",d[1]);
    if(!img.hasAttribute("decoding"))img.setAttribute("decoding","async");
  }
  function balayer(racine){
    var l=(racine||document).querySelectorAll?
      (racine||document).querySelectorAll('img[src*="/img/"]'):[];
    for(var k=0;k<l.length;k++)coter(l[k]);
  }
  balayer(document);
  if(window.MutationObserver){
    new MutationObserver(function(muts){
      for(var i=0;i<muts.length;i++){
        var aj=muts[i].addedNodes;
        for(var j=0;j<aj.length;j++){
          var n=aj[j];if(n.nodeType!==1)continue;
          if(n.tagName==="IMG")coter(n);else balayer(n);
        }
      }
    }).observe(document.documentElement,{childList:true,subtree:true});
  }
  document.addEventListener("DOMContentLoaded",function(){balayer(document);});
